create table eba_demo_dg_dept (
    deptno number(4, 0)
        generated by default on null as identity
    not null enable,
    dname  varchar2(50 byte),
    loc    varchar2(50 byte)
);

alter table eba_demo_dg_dept
    add constraint eba_demo_dg_dept_pk primary key ( deptno )
        using index enable;


